import{_ as a,a as e,b as r,c as i,d as l,e as o,f as p,g as s}from"./chunks/dark-detail.DAFPwsOs.js";import{_ as n,o as d,c,a2 as x}from"./chunks/framework.DDY-poMm.js";const q=JSON.parse('{"title":"BTX Wallet（Web3 钱包）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/app/wallet.md","filePath":"zh/app/wallet.md","lastUpdated":1791353800000}'),h={name:"zh/app/wallet.md"};function g(b,t,f,m,u,v){return d(),c("div",null,[...t[0]||(t[0]=[x('<h1 id="btx-wallet-web3-钱包" tabindex="-1">BTX Wallet（Web3 钱包） <a class="header-anchor" href="#btx-wallet-web3-钱包" aria-label="Permalink to &quot;BTX Wallet（Web3 钱包）&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">内测中</p><p>BTX Wallet 目前处于内测阶段。如需了解或体验，请<a href="/CoinExchange/zh/contact/">联系我们</a>。</p></div><p>BTX Wallet 是一款<strong>自托管的 Web3 钱包</strong>：用户用 USDC / USDT 直接在链上买卖 <strong>xStocks 代币化美股与 ETF</strong>，资产始终在用户自己的链上地址里。</p><p>用户最常问的是「接的是哪家券商、我的持仓在哪」。在 BTX Wallet 里，每一笔成交、每一份持仓都记录在区块链上，用户自己就能在区块链浏览器查证。</p><h2 id="与交易所-app-的区别" tabindex="-1">与交易所 App 的区别 <a class="header-anchor" href="#与交易所-app-的区别" aria-label="Permalink to &quot;与交易所 App 的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>交易所 App</th><th>BTX Wallet</th></tr></thead><tbody><tr><td>资产由谁保管</td><td>平台托管</td><td><strong>用户自己</strong>（私钥只在用户手机里）</td></tr><tr><td>是否需要注册账号</td><td>需要</td><td><strong>不需要</strong>，创建或导入钱包即可使用</td></tr><tr><td>成交在哪里发生</td><td>平台撮合</td><td><strong>链上成交</strong>，可在区块链浏览器查证</td></tr><tr><td>美股持仓</td><td>平台记账</td><td><strong>代币化股票</strong>（xStocks），由发行方持有的正股 1:1 支持</td></tr></tbody></table><h2 id="能力一览" tabindex="-1">能力一览 <a class="header-anchor" href="#能力一览" aria-label="Permalink to &quot;能力一览&quot;">​</a></h2><h3 id="自托管-平台不碰私钥" tabindex="-1">自托管，平台不碰私钥 <a class="header-anchor" href="#自托管-平台不碰私钥" aria-label="Permalink to &quot;自托管，平台不碰私钥&quot;">​</a></h3><p>助记词只保存在用户手机里，用设备的安全芯片加密，服务器上没有任何私钥。支持 Face ID；密码连续输错会逐级延长锁定时间。一个 App 可管理多个钱包，也可导入已有私钥。</p><h3 id="链上买卖代币化美股" tabindex="-1">链上买卖代币化美股 <a class="header-anchor" href="#链上买卖代币化美股" aria-label="Permalink to &quot;链上买卖代币化美股&quot;">​</a></h3><p>用 USDC / USDT 直接买卖 xStocks 美股与 ETF，下单前列明价格、滑点和费用。签名前自动核对这笔交易会让余额和授权发生什么变化，有异常不会继续；滑点偏高时会提醒并要求二次确认。美股休市时仍可链上交易，但会明确提示「休市期间链上价格可能偏离」。</p><h3 id="专业行情" tabindex="-1">专业行情 <a class="header-anchor" href="#专业行情" aria-label="Permalink to &quot;专业行情&quot;">​</a></h3><p>K 线支持 15 分钟、1 小时、4 小时、日线、周线，带均线、成交额和十字光标，可拖动、可缩放。K 线下方的盘面显示 24 小时买卖笔数对比和实时成交。美股休市时标明最近一次收盘时间（美东）。</p><h3 id="公司概况" tabindex="-1">公司概况 <a class="header-anchor" href="#公司概况" aria-label="Permalink to &quot;公司概况&quot;">​</a></h3><p>每只股票都有中英双语的公司资料：公司、股票代码、行业、类型、上市时间、上市交易所、官网、公司简介。资料整理自公开信息，官网只采用官方登记或可查证的地址。</p><h3 id="资讯与公告" tabindex="-1">资讯与公告 <a class="header-anchor" href="#资讯与公告" aria-label="Permalink to &quot;资讯与公告&quot;">​</a></h3><p>资讯由 AI 依据公开报道整理成中英双语图文。发布前自动核对两种语言的日期和金额是否一致，不一致的不会发布。另附美国证监会（SEC）上的公司官方公告。</p><h3 id="加密货币行情" tabindex="-1">加密货币行情 <a class="header-anchor" href="#加密货币行情" aria-label="Permalink to &quot;加密货币行情&quot;">​</a></h3><p>行情页分「美股 | 加密货币」两栏。主流币行情取自主流交易所现货市场，平台币价格与本平台一致。加密货币只看行情，不在钱包内交易。</p><h3 id="外观与语言" tabindex="-1">外观与语言 <a class="header-anchor" href="#外观与语言" aria-label="Permalink to &quot;外观与语言&quot;">​</a></h3><p>浅色 / 深色外观，中文 / 英文，可跟随系统或手动切换。</p><h2 id="界面一览" tabindex="-1">界面一览 <a class="header-anchor" href="#界面一览" aria-label="Permalink to &quot;界面一览&quot;">​</a></h2><div style="display:flex;flex-wrap:wrap;gap:28px 20px;justify-content:center;margin:32px 0;"><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+a+'" alt="首页" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>首页</b><br>行情卡片、快捷操作与今日涨跌榜 </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+e+'" alt="行情 · 美股" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>行情 · 美股</b><br>已上架的代币化美股与 ETF，7 天走势一目了然 </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+r+'" alt="行情 · 加密货币" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>行情 · 加密货币</b><br>主流币与平台币行情，只看行情 </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+i+'" alt="K 线" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>K 线</b><br>15 分钟到周线，均线、成交额与十字光标 </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+l+'" alt="盘面" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>盘面</b><br>24 小时买卖对比与实时成交 </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+o+'" alt="公司概况" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>公司概况</b><br>公司、行业、上市时间、交易所与官网 </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+p+'" alt="资讯" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>资讯</b><br>AI 整理的中英双语图文资讯 </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+s+'" alt="深色模式" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>深色模式</b><br>浅色 / 深色可切换 </figcaption></figure></div><div class="tip custom-block"><p class="custom-block-title">关于这些截图</p><p>为内测版本在模拟器中的截图，其中价格与资讯为测试环境的数据。</p></div><h2 id="运营后台" tabindex="-1">运营后台 <a class="header-anchor" href="#运营后台" aria-label="Permalink to &quot;运营后台&quot;">​</a></h2><p>在运营后台的「Web3 钱包」菜单中管理：</p><ul><li><strong>钱包代币</strong>：从发行方官方清单同步，选择上架哪些股票、排序</li><li><strong>兑换记录与统计</strong>：每笔买卖、成交额与平台服务费</li><li><strong>钱包用户</strong>：已创建 / 导入的钱包地址与活跃情况</li><li><strong>钱包资讯 / 代币概况</strong>：查看、修改、下架，或重新生成</li><li><strong>钱包设置</strong>：平台服务费、支付币种、资讯更新频率、加密货币币种</li></ul><h2 id="安全须知" tabindex="-1">安全须知 <a class="header-anchor" href="#安全须知" aria-label="Permalink to &quot;安全须知&quot;">​</a></h2><ul><li>平台不保存私钥，<strong>助记词一旦丢失无法找回</strong>，请务必离线备份。</li><li>代币化股票由发行方发行。持有人不享有股东投票权，发行方可在特定情况下暂停转账。</li><li>链上交易一经确认不可撤销。</li></ul><p>BTX Wallet 包含在「落地陪跑 FDE 版」套餐中（含钱包 App 与后台的全部源码），详见<a href="/CoinExchange/zh/intro/pricing">价格与销售套餐</a>。</p>',30)])])}const k=n(h,[["render",g]]);export{q as __pageData,k as default};
